/* 최상단의 선언 */
scwin.isMain = function() {
	return true;
}

scwin.onpageload = function() {

	/* 메뉴 */
	if(!scutilo.isEmpty(scwin.pgmId)){ 
	   $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId);	
	}

    //이미지 맵 반응형 처리
    $('#mf_stepImg1').rwdImageMaps();
};

scwin.onpageunload = function() {

};
/* 클릭한 경매용어 */
scwin.srchTrm="";

/**
 * 경매용어 검색 팝업창 오픈
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.04.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_auctnTrmSrch_onclick = function(e) {
    /********* Popup Settings *********/
	var winW = window.innerWidth;
	var winH = window.innerHeight;

	/* small popup size */
	var popupW = 700;
	var popupH = 450;

	var popupX = (winW/2) - (popupW/2);
	var popupY = (winH/2) - (popupH/2);

	/**
	 * 공지사항 openPopUp option설정
	 */
	var options = {
		id: "auctnTrmPopUp",
		type: "wframePopup",
		popupName: "경매용어 검색 팝업창",
		top:popupY,
		left:popupX,
		width:popupW,
		height:popupH,
		modal: false
	};

	var obj = {
		"flag" : "Y",
		"srchTrm" : scwin.srchTrm
	}


    com.win.openPopup("/pgj/ui/pgj100/PGJ171P01.xml",options,obj);

};

