/**
 * 경매용어 클릭시 팝업창 중복체크후 팝업창 오픈 하고 검색
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.06.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.srchAuctnTrm = function() {
	const id = this.getID();
	const popId = "auctnTrmPopUp";
	scwin.srchTrm = $p.getComponentById(id).getValue();
	if(scwin.popupDpcnChk(popId)) {
		scwin.btn_auctnTrmSrch_onclick();
	} else {
		$p.closePopup(popId);
		/* 비동기 방식이라 close와 open이 동시에 되서 둘사이의 0.1간격을 둠 */
		setTimeout(()=>scwin.btn_auctnTrmSrch_onclick(),100);
	}

};

/**
 * 팝업창 중복 생성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.10.06.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.popupDpcnChk = function(id){
	var popupList = WebSquare.uiplugin.popup.popupList;
	if (popupList.length!=0) {
		for (var idx = 0; idx < popupList.length; idx++) {
			if (WebSquare.uiplugin.popup.popupList[idx].id.indexOf(id) != -1) {
				return false;
			}
		}
	}
	return true;
}

let openClosedFlag = "Y";

/**
 * 전체보기 클릭시 모든 경매절차 open,close
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.11.22.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.btn_auctnPrcdAll_onclick = function(e) {
	btn_auctnPrcdAll.toggleClass("bt_more_m");
	if ( openClosedFlag == "Y" ) {
		openClosedFlag = "N"
		btn_auctnPrcdAll.setLabel("전체 줄이기");
		acd_auctnPrcd1.openPanel("panels1")
		acd_auctnPrcd2.openPanel("panels2")
		acd_auctnPrcd3.openPanel("panels3")
		acd_auctnPrcd4.openPanel("panels4")
		acd_auctnPrcd5.openPanel("panels5")
		acd_auctnPrcd6.openPanel("panels6")
		acd_auctnPrcd7.openPanel("panels7")
		acd_auctnPrcd8.openPanel("panels8")
		acd_auctnPrcd9.openPanel("panels9")
	} else {
		openClosedFlag = "Y"
		btn_auctnPrcdAll.setLabel("전체 자세히보기");
		acd_auctnPrcd1.closePanel("panels1")
		acd_auctnPrcd2.closePanel("panels2")
		acd_auctnPrcd3.closePanel("panels3")
		acd_auctnPrcd4.closePanel("panels4")
		acd_auctnPrcd5.closePanel("panels5")
		acd_auctnPrcd6.closePanel("panels6")
		acd_auctnPrcd7.closePanel("panels7")
		acd_auctnPrcd8.closePanel("panels8")
		acd_auctnPrcd9.closePanel("panels9")
	}
};
